#!ibl edition=2
$n = [limbs:browser]{op:"navigate", url:"http://127.0.0.1:8979/board", wait:"load"}
$s = [limbs:browser]{op:"snapshot"}
$card = ($s.snapshot >> [table:filter]{where:($e)=>contains($e.name,"W-1004")})
$head = ($s.snapshot >> [table:filter]{where:($e)=>$e.role=="heading" and contains($e.name,"오늘 처리")})
$y0 = [limbs:browser]{op:"evaluate", expression:"window.scrollY"}
$d = [limbs:browser]{op:"drag", source_ref:$card[0].ref, target_ref:$head[0].ref}
$e1 = [limbs:browser]{op:"evaluate", expression:"Array.from(document.querySelectorAll('.col')).filter(c=>['지연','오늘 처리'].includes(c.dataset.col)).map(c=>c.dataset.col+':'+Array.from(c.querySelectorAll('.card')).map(x=>x.dataset.id).join(',')).join(' | ') + ' scrollY=' + window.scrollY"}
return {y0:$y0.result, card:$card, head:$head, drag:$d, after:$e1.result}
